package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.List;
import java.util.stream.Collectors;

import org.eclipse.rdf4j.benchmark.common.ThemeQueryCatalog;
import org.eclipse.rdf4j.benchmark.rio.util.ThemeDataSetGenerator.Theme;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.vocabulary.RDF;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * A native root compile tries the aggregate route first and falls back to the row route on the same planner. When the
 * aggregate attempt declines after it froze the planner's slot layout (the nested GROUP's input semantics are prepared
 * only after the freeze), the row fallback must not run on that consumed planner: it used to throw
 * {@code IllegalStateException: slot layout is already frozen} instead of compiling or declining. PHARMA q9 of the
 * theme catalog has that shape (an aggregate sub-select whose body holds a null-rejected OPTIONAL with a BIND, below an
 * outer aggregate that joins it with more patterns); the failure happens on the first evaluation of a fresh store, so
 * it needs no plan-cache hit.
 */
public class LmdbNativeDeclinedAggregateRootTest {

	private static final String PHARMA = "http://example.com/theme/pharma/";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";

	/**
	 * The smallest shape found: an outer COUNT over a join of an aggregate sub-select (body: null-rejected OPTIONAL
	 * with a BIND) with one more triple pattern.
	 */
	private static final String MINIMAL_QUERY = String.join("\n",
			"PREFIX pharma: <" + PHARMA + ">",
			"SELECT (COUNT(DISTINCT ?drug) AS ?count) WHERE {",
			"  { SELECT ?drug (AVG(?effect) AS ?avgEffect) WHERE {",
			"      ?arm pharma:armDrug ?drug ; pharma:hasResult ?result .",
			"      ?result pharma:effectSize ?effect .",
			"      OPTIONAL { ?result pharma:responseRate ?rate . BIND(?rate AS ?optRate) }",
			"      FILTER(?optRate > 0.2)",
			"    } GROUP BY ?drug HAVING(AVG(?effect) > 0.4) }",
			"  ?drug pharma:hasSideEffect ?se .",
			"}");

	/**
	 * The same sub-select under a LIMIT: the root pipeline peels the modifier and runs the aggregate and row attempts
	 * on its own planner, so it needs the same fallback rule.
	 */
	private static final String MODIFIER_QUERY = String.join("\n",
			"PREFIX pharma: <" + PHARMA + ">",
			"SELECT (COUNT(DISTINCT ?drug) AS ?count) WHERE {",
			"  { SELECT ?drug (AVG(?effect) AS ?avgEffect) WHERE {",
			"      ?arm pharma:armDrug ?drug ; pharma:hasResult ?result .",
			"      ?result pharma:effectSize ?effect .",
			"      OPTIONAL { ?result pharma:responseRate ?rate . BIND(?rate AS ?optRate) }",
			"      FILTER(?optRate > 0.2)",
			"    } GROUP BY ?drug HAVING(AVG(?effect) > 0.4) LIMIT 100 }",
			"  ?drug pharma:hasSideEffect ?se .",
			"}");

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir,
				new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(true)));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI trial = vf.createIRI(PHARMA, "trial/0");
			IRI arm = vf.createIRI(PHARMA, "arm/0");
			IRI drug = vf.createIRI(PHARMA, "drug/0");
			IRI result = vf.createIRI(PHARMA, "result/0");
			conn.add(trial, RDF.TYPE, vf.createIRI(PHARMA, "ClinicalTrial"));
			conn.add(trial, vf.createIRI(PHARMA, "hasArm"), arm);
			conn.add(arm, vf.createIRI(PHARMA, "armDrug"), drug);
			conn.add(arm, vf.createIRI(PHARMA, "hasResult"), result);
			conn.add(result, vf.createIRI(PHARMA, "effectSize"), vf.createLiteral(0.5d));
			conn.add(result, vf.createIRI(PHARMA, "responseRate"), vf.createLiteral(0.3d));
			conn.add(drug, vf.createIRI(PHARMA, "hasSideEffect"), vf.createIRI(PHARMA, "side-effect/0"));
			conn.add(drug, vf.createIRI(PHARMA, "indicatedFor"), vf.createIRI(PHARMA, "disease/8"));
		}
	}

	@AfterEach
	public void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	@Test
	public void pharmaQ9EvaluatesNativelyOnFirstEvaluation() {
		String query = ThemeQueryCatalog.queryFor(Theme.PHARMA, 9);

		List<String> nativeRows = rows(query, true);
		List<String> generic = rows(query, false);
		assertThat(generic)
				.as("interpreted oracle: drug/0 averages 0.5 > 0.4, has a side effect and is indicated for disease/8")
				.containsExactly("count=\"1\"^^<http://www.w3.org/2001/XMLSchema#integer>");
		assertThat(nativeRows).as("native evaluation must match the interpreted engine").isEqualTo(generic);
	}

	@Test
	public void declinedNestedAggregateFallsBackWithoutReusingFrozenLayout() {
		List<String> nativeRows = rows(MINIMAL_QUERY, true);
		List<String> generic = rows(MINIMAL_QUERY, false);
		assertThat(generic).as("interpreted oracle")
				.containsExactly("count=\"1\"^^<http://www.w3.org/2001/XMLSchema#integer>");
		assertThat(nativeRows).as("native evaluation must match the interpreted engine").isEqualTo(generic);
	}

	@Test
	public void declinedNestedAggregateUnderModifierFallsBackWithoutReusingFrozenLayout() {
		List<String> nativeRows = rows(MODIFIER_QUERY, true);
		List<String> generic = rows(MODIFIER_QUERY, false);
		assertThat(generic).as("interpreted oracle")
				.containsExactly("count=\"1\"^^<http://www.w3.org/2001/XMLSchema#integer>");
		assertThat(nativeRows).as("native evaluation must match the interpreted engine").isEqualTo(generic);
	}

	private List<String> rows(String query, boolean nativeEnabled) {
		String previous = System.getProperty(NATIVE_FLAG);
		System.setProperty(NATIVE_FLAG, Boolean.toString(nativeEnabled));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return QueryResults.asList(conn.prepareTupleQuery(query).evaluate())
					.stream()
					.map(bs -> bs.getBindingNames()
							.stream()
							.sorted()
							.map(name -> name + "=" + bs.getValue(name))
							.collect(Collectors.joining("|")))
					.collect(Collectors.toList());
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previous);
			}
		}
	}
}
